  public WeakReference<FakePlayer> setupBeforeTrigger(ServerLevel sw, String name, UUID ownerId) {
    WeakReference<FakePlayer> fakePlayer = FakePlayerUtil.initFakePlayer(sw, name, ownerId);
    if (fakePlayer == null) {
