    fakePlayer.get().setYRot(EntityUtil.getYawFromFacing(this.getCurrentFacing()));
    return fakePlayer;
  }

  public void setLitProperty(boolean lit) {
    BlockState st = this.getBlockState();
    if (!st.hasProperty(BlockCyclic.LIT)) {
      return;
